-- v4.3.7 deterministic bootstrap deployment and Embedding governance.
MERGE INTO CX_PLATFORM_CAPABILITIES d USING (SELECT 'deployment_governance' CAPABILITY_KEY FROM DUAL) s ON (d.CAPABILITY_KEY=s.CAPABILITY_KEY)
WHEN NOT MATCHED THEN INSERT (CAPABILITY_KEY,MANDATORY) VALUES (s.CAPABILITY_KEY,'Y');
MERGE INTO CX_PLATFORM_CAPABILITIES d USING (SELECT 'embedding_governance' CAPABILITY_KEY FROM DUAL) s ON (d.CAPABILITY_KEY=s.CAPABILITY_KEY)
WHEN NOT MATCHED THEN INSERT (CAPABILITY_KEY,MANDATORY) VALUES (s.CAPABILITY_KEY,'Y');
MERGE INTO CX_PLATFORM_CAPABILITIES d USING (SELECT 'embedding_managed_worker' CAPABILITY_KEY FROM DUAL) s ON (d.CAPABILITY_KEY=s.CAPABILITY_KEY)
WHEN NOT MATCHED THEN INSERT (CAPABILITY_KEY,MANDATORY) VALUES (s.CAPABILITY_KEY,'N');
MERGE INTO CX_PLATFORM_CAPABILITY_DEPENDENCIES d USING (SELECT 'deployment_governance' CAPABILITY_KEY,'audit_write' DEPENDS_ON_KEY FROM DUAL) s ON (d.CAPABILITY_KEY=s.CAPABILITY_KEY AND d.DEPENDS_ON_KEY=s.DEPENDS_ON_KEY)
WHEN NOT MATCHED THEN INSERT (CAPABILITY_KEY,DEPENDS_ON_KEY) VALUES (s.CAPABILITY_KEY,s.DEPENDS_ON_KEY);
MERGE INTO CX_PLATFORM_CAPABILITY_DEPENDENCIES d USING (SELECT 'embedding_governance' CAPABILITY_KEY,'agents' DEPENDS_ON_KEY FROM DUAL) s ON (d.CAPABILITY_KEY=s.CAPABILITY_KEY AND d.DEPENDS_ON_KEY=s.DEPENDS_ON_KEY)
WHEN NOT MATCHED THEN INSERT (CAPABILITY_KEY,DEPENDS_ON_KEY) VALUES (s.CAPABILITY_KEY,s.DEPENDS_ON_KEY);
MERGE INTO CX_PLATFORM_CAPABILITY_DEPENDENCIES d USING (SELECT 'embedding_governance' CAPABILITY_KEY,'audit_write' DEPENDS_ON_KEY FROM DUAL) s ON (d.CAPABILITY_KEY=s.CAPABILITY_KEY AND d.DEPENDS_ON_KEY=s.DEPENDS_ON_KEY)
WHEN NOT MATCHED THEN INSERT (CAPABILITY_KEY,DEPENDS_ON_KEY) VALUES (s.CAPABILITY_KEY,s.DEPENDS_ON_KEY);
MERGE INTO CX_PLATFORM_CAPABILITY_DEPENDENCIES d USING (SELECT 'embedding_managed_worker' CAPABILITY_KEY,'embedding_governance' DEPENDS_ON_KEY FROM DUAL) s ON (d.CAPABILITY_KEY=s.CAPABILITY_KEY AND d.DEPENDS_ON_KEY=s.DEPENDS_ON_KEY)
WHEN NOT MATCHED THEN INSERT (CAPABILITY_KEY,DEPENDS_ON_KEY) VALUES (s.CAPABILITY_KEY,s.DEPENDS_ON_KEY);
DECLARE
  PROCEDURE ddl(s VARCHAR2) IS BEGIN EXECUTE IMMEDIATE s; EXCEPTION WHEN OTHERS THEN IF SQLCODE != -955 THEN RAISE; END IF; END;
  PROCEDURE add_col(s VARCHAR2) IS BEGIN EXECUTE IMMEDIATE s; EXCEPTION WHEN OTHERS THEN IF SQLCODE != -1430 THEN RAISE; END IF; END;
BEGIN
  ddl('CREATE TABLE CX_DEPLOYMENT_RUNS (RUN_ID VARCHAR2(128) PRIMARY KEY, RUN_MODE VARCHAR2(32) NOT NULL, DATABASE_DIALECT VARCHAR2(32) NOT NULL, EDITION VARCHAR2(32) NOT NULL, PACKAGE_VERSION VARCHAR2(32) NOT NULL, STATUS VARCHAR2(64) NOT NULL, READINESS_JSON CLOB DEFAULT ''{}'' NOT NULL, PLAN_DIGEST VARCHAR2(64) NOT NULL, JOURNAL_DIGEST VARCHAR2(128), DEPLOYMENT_AGENT_ID VARCHAR2(128), CURRENT_STEP VARCHAR2(128), FAILURE_CODE VARCHAR2(128), FAILURE_DETAIL VARCHAR2(2000), CREATED_BY VARCHAR2(128) NOT NULL, CREATED_AT TIMESTAMP DEFAULT SYSTIMESTAMP NOT NULL, UPDATED_AT TIMESTAMP DEFAULT SYSTIMESTAMP NOT NULL, COMPLETED_AT TIMESTAMP)');
  ddl('CREATE TABLE CX_DEPLOYMENT_STEPS (STEP_ID VARCHAR2(128) PRIMARY KEY, RUN_ID VARCHAR2(128) NOT NULL, STEP_KEY VARCHAR2(128) NOT NULL, STEP_ORDER NUMBER(10,0) NOT NULL, STATUS VARCHAR2(64) NOT NULL, ACTION_DIGEST VARCHAR2(64) NOT NULL, RESULT_JSON CLOB DEFAULT ''{}'' NOT NULL, ERROR_CODE VARCHAR2(128), RETRY_CLASS VARCHAR2(64) DEFAULT ''RETRYABLE'' NOT NULL, ATTEMPT_COUNT NUMBER(10,0) DEFAULT 0 NOT NULL, STARTED_AT TIMESTAMP, COMPLETED_AT TIMESTAMP, CREATED_AT TIMESTAMP DEFAULT SYSTIMESTAMP NOT NULL, UPDATED_AT TIMESTAMP DEFAULT SYSTIMESTAMP NOT NULL, CONSTRAINT UK_CX_DEPLOY_STEP UNIQUE(RUN_ID,STEP_KEY))');
  ddl('CREATE TABLE CX_DEPLOYMENT_EVIDENCE (EVIDENCE_ID VARCHAR2(128) PRIMARY KEY, RUN_ID VARCHAR2(128) NOT NULL, EVIDENCE_TYPE VARCHAR2(64) NOT NULL, PAYLOAD_JSON CLOB NOT NULL, PAYLOAD_DIGEST VARCHAR2(64) NOT NULL, STATUS VARCHAR2(32) DEFAULT ''RECORDED'' NOT NULL, CREATED_AT TIMESTAMP DEFAULT SYSTIMESTAMP NOT NULL)');
  ddl('CREATE TABLE CX_DEPLOYMENT_LEASES (LEASE_KEY VARCHAR2(128) PRIMARY KEY, RUN_ID VARCHAR2(128) NOT NULL, NODE_ID VARCHAR2(128) NOT NULL, FENCING_TOKEN NUMBER(19,0) DEFAULT 1 NOT NULL, LEASE_EXPIRES_AT TIMESTAMP NOT NULL, STATUS VARCHAR2(32) DEFAULT ''ACTIVE'' NOT NULL, UPDATED_AT TIMESTAMP DEFAULT SYSTIMESTAMP NOT NULL)');
  ddl('CREATE INDEX IDX_CX_DEPLOY_RUN_STATUS ON CX_DEPLOYMENT_RUNS(STATUS,CREATED_AT)');
  ddl('CREATE INDEX IDX_CX_DEPLOY_EVIDENCE_RUN ON CX_DEPLOYMENT_EVIDENCE(RUN_ID,CREATED_AT)');
  ddl('CREATE TABLE CX_EMBEDDING_PROFILES (PROFILE_ID VARCHAR2(128) PRIMARY KEY, PROFILE_KEY VARCHAR2(128) UNIQUE NOT NULL, PROVIDER_URL VARCHAR2(512), MODEL_ID VARCHAR2(256) NOT NULL, MODEL_FINGERPRINT VARCHAR2(256), API_KEY_CIPHER CLOB, SECRET_REFERENCE VARCHAR2(512), EXECUTION_MODE VARCHAR2(32) NOT NULL, DIMENSION NUMBER(10,0) DEFAULT 0 NOT NULL, DISTANCE_METRIC VARCHAR2(32) DEFAULT ''COSINE'' NOT NULL, NORMALIZE_VECTORS CHAR(1) DEFAULT ''Y'' NOT NULL, PREPROCESSING_JSON CLOB DEFAULT ''{}'' NOT NULL, MODALITIES_JSON CLOB DEFAULT ''["TEXT"]'' NOT NULL, STATUS VARCHAR2(32) DEFAULT ''DRAFT'' NOT NULL, HEALTH_STATE VARCHAR2(32) DEFAULT ''UNKNOWN'' NOT NULL, VERSION NUMBER(19,0) DEFAULT 1 NOT NULL, UPDATED_BY VARCHAR2(128), UPDATE_REASON VARCHAR2(2000), CREATED_AT TIMESTAMP DEFAULT SYSTIMESTAMP NOT NULL, UPDATED_AT TIMESTAMP DEFAULT SYSTIMESTAMP NOT NULL)');
  ddl('CREATE TABLE CX_EMBEDDING_CONTRACTS (CONTRACT_ID VARCHAR2(128) PRIMARY KEY, PROFILE_ID VARCHAR2(128) NOT NULL, CONTRACT_VERSION NUMBER(19,0) NOT NULL, PROVIDER_IDENTITY VARCHAR2(512), MODEL_FINGERPRINT VARCHAR2(256), DIMENSION NUMBER(10,0) NOT NULL, DISTANCE_METRIC VARCHAR2(32) NOT NULL, NORMALIZE_VECTORS CHAR(1) NOT NULL, PREPROCESSING_JSON CLOB NOT NULL, MODALITIES_JSON CLOB NOT NULL, EXECUTION_MODE VARCHAR2(32) NOT NULL, STATUS VARCHAR2(32) DEFAULT ''DRAFT'' NOT NULL, CONTRACT_DIGEST VARCHAR2(64) NOT NULL, CREATED_BY VARCHAR2(128) NOT NULL, CREATED_AT TIMESTAMP DEFAULT SYSTIMESTAMP NOT NULL, CONSTRAINT UK_CX_EMBED_CONTRACT UNIQUE(PROFILE_ID,CONTRACT_VERSION))');
  ddl('CREATE TABLE CX_EMBEDDING_SPACES (SPACE_ID VARCHAR2(128) PRIMARY KEY, SPACE_KEY VARCHAR2(128) UNIQUE NOT NULL, CONTRACT_ID VARCHAR2(128), STATUS VARCHAR2(32) DEFAULT ''DRAFT'' NOT NULL, IS_DEFAULT CHAR(1) DEFAULT ''N'' NOT NULL, WRITE_ENABLED CHAR(1) DEFAULT ''N'' NOT NULL, VALIDATION_STATE VARCHAR2(32) DEFAULT ''UNVERIFIED'' NOT NULL, PHYSICAL_REF VARCHAR2(256), CREATED_BY VARCHAR2(128) NOT NULL, REASON VARCHAR2(2000), CREATED_AT TIMESTAMP DEFAULT SYSTIMESTAMP NOT NULL, UPDATED_AT TIMESTAMP DEFAULT SYSTIMESTAMP NOT NULL)');
  ddl('CREATE TABLE CX_EMBEDDING_BINDINGS (BINDING_ID VARCHAR2(128) PRIMARY KEY, BINDING_SCOPE VARCHAR2(32) NOT NULL, BINDING_SUBJECT_ID VARCHAR2(128) NOT NULL, PROFILE_ID VARCHAR2(128), SPACE_ID VARCHAR2(128), STATUS VARCHAR2(32) DEFAULT ''ACTIVE'' NOT NULL, VERSION NUMBER(19,0) DEFAULT 1 NOT NULL, APPROVED_BY VARCHAR2(128), REASON VARCHAR2(2000) NOT NULL, CREATED_AT TIMESTAMP DEFAULT SYSTIMESTAMP NOT NULL, UPDATED_AT TIMESTAMP DEFAULT SYSTIMESTAMP NOT NULL, CONSTRAINT UK_CX_EMBED_BINDING UNIQUE(BINDING_SCOPE,BINDING_SUBJECT_ID))');
  ddl('CREATE TABLE CX_EMBEDDING_PROBES (PROBE_ID VARCHAR2(128) PRIMARY KEY, PROFILE_ID VARCHAR2(128) NOT NULL, PROBE_SCOPE VARCHAR2(32) NOT NULL, STATUS VARCHAR2(32) NOT NULL, OBSERVED_DIMENSION NUMBER(10,0), OBSERVED_MODEL VARCHAR2(256), OBSERVED_FINGERPRINT VARCHAR2(256), RESULT_JSON CLOB DEFAULT ''{}'' NOT NULL, ERROR_CODE VARCHAR2(128), CREATED_BY VARCHAR2(128) NOT NULL, CREATED_AT TIMESTAMP DEFAULT SYSTIMESTAMP NOT NULL)');
  ddl('CREATE TABLE CX_EMBEDDING_JOBS (JOB_ID VARCHAR2(128) PRIMARY KEY, JOB_KIND VARCHAR2(32) NOT NULL, SOURCE_SPACE_ID VARCHAR2(128), TARGET_SPACE_ID VARCHAR2(128), STATUS VARCHAR2(32) DEFAULT ''PENDING'' NOT NULL, REQUESTED_BY VARCHAR2(128) NOT NULL, REASON VARCHAR2(2000) NOT NULL, IDEMPOTENCY_KEY VARCHAR2(128) UNIQUE NOT NULL, INPUT_JSON CLOB DEFAULT ''{}'' NOT NULL, RESULT_JSON CLOB DEFAULT ''{}'' NOT NULL, WORKER_ID VARCHAR2(128), LEASE_EXPIRES_AT TIMESTAMP, FENCING_TOKEN NUMBER(19,0) DEFAULT 1 NOT NULL, CREATED_AT TIMESTAMP DEFAULT SYSTIMESTAMP NOT NULL, UPDATED_AT TIMESTAMP DEFAULT SYSTIMESTAMP NOT NULL, COMPLETED_AT TIMESTAMP)');
  ddl('CREATE TABLE CX_EMBEDDING_HISTORY (HISTORY_ID VARCHAR2(128) PRIMARY KEY, OBJECT_TYPE VARCHAR2(32) NOT NULL, OBJECT_ID VARCHAR2(128) NOT NULL, ACTION VARCHAR2(64) NOT NULL, FROM_VERSION NUMBER(19,0), TO_VERSION NUMBER(19,0), ACTOR VARCHAR2(128) NOT NULL, REASON VARCHAR2(2000) NOT NULL, DETAIL_JSON CLOB DEFAULT ''{}'' NOT NULL, CREATED_AT TIMESTAMP DEFAULT SYSTIMESTAMP NOT NULL)');
  add_col('ALTER TABLE ENTITY_EMBEDDINGS ADD (EMBEDDING_SPACE_ID VARCHAR2(128) DEFAULT ''LEGACY_DEFAULT'' NOT NULL)');
  add_col('ALTER TABLE ENTITY_EMBEDDINGS ADD (EMBEDDING_PROFILE_ID VARCHAR2(128))');
  add_col('ALTER TABLE ENTITY_EMBEDDINGS ADD (EMBEDDING_CONTRACT_ID VARCHAR2(128))');
  add_col('ALTER TABLE ENTITY_EMBEDDINGS ADD (CONTENT_DIGEST VARCHAR2(64))');
  add_col('ALTER TABLE ENTITY_EMBEDDINGS ADD (SOURCE_MODE VARCHAR2(32) DEFAULT ''LEGACY'' NOT NULL)');
  add_col('ALTER TABLE ENTITY_EMBEDDINGS ADD (VALIDATION_STATUS VARCHAR2(32) DEFAULT ''UNVERIFIED'' NOT NULL)');
  BEGIN EXECUTE IMMEDIATE 'ALTER TABLE ENTITY_EMBEDDINGS DROP CONSTRAINT PK_ENTITY_EMBEDDINGS'; EXCEPTION WHEN OTHERS THEN IF SQLCODE != -2443 THEN RAISE; END IF; END;
  ddl('ALTER TABLE ENTITY_EMBEDDINGS ADD CONSTRAINT PK_ENTITY_EMBEDDINGS PRIMARY KEY (ENTITY_ID,ENTITY_TYPE,EMBEDDING_SPACE_ID)');
  ddl('CREATE INDEX IDX_EE_SPACE_CONTRACT ON ENTITY_EMBEDDINGS(EMBEDDING_SPACE_ID,EMBEDDING_CONTRACT_ID)');
END;
/
MERGE INTO CX_EMBEDDING_SPACES d USING (SELECT 'SPACE_LEGACY_DEFAULT' SPACE_ID,'LEGACY_DEFAULT' SPACE_KEY FROM DUAL) s ON (d.SPACE_KEY=s.SPACE_KEY)
WHEN NOT MATCHED THEN INSERT (SPACE_ID,SPACE_KEY,STATUS,IS_DEFAULT,WRITE_ENABLED,VALIDATION_STATE,CREATED_BY,REASON) VALUES (s.SPACE_ID,s.SPACE_KEY,'ARCHIVED','N','N','UNVERIFIED','SYSTEM_MIGRATION','v4.3.7 adoption of existing vectors');
